describe('AC5: storyBlock', () => {
    const text = plan([
        { id: 'F-1.1', wave: 1, files: '`.agents/core/a.js` (new)' },
        { id: 'F-1.10', wave: 2, files: '`.agents/core/ten.js` (new)' },
        { id: 'F-1.2', wave: 3, files: '`.agents/core/b.js` (new)' },
    ]);

    it('storyBlock_knownBullet_startsAtItsHeaderAndStopsBeforeTheNextStory', () => {
        const block = storyBlock(text, 'F-1.1');
        expect(block.startsWith('* **Story F-1.1 (S): Title F-1.1**')).toBe(true);
        expect(block).toContain('`.agents/core/a.js` (new)');
        expect(block).not.toContain('F-1.10');
        expect(block).not.toContain('b.js');
    });

    it('storyBlock_idThatIsAPrefixOfAnother_matchesExactly', () => {
        const block = storyBlock(text, 'F-1.10');
        expect(block.startsWith('* **Story F-1.10 (S)')).toBe(true);
        expect(block).toContain('ten.js');
        expect(block).not.toContain('a.js');
    });

    it('storyBlock_unknownId_returnsNull', () => {
        expect(storyBlock(text, 'F-9.9')).toBeNull();
    });

    it('storyBlock_crlfInput_equalsTheLfBlock', () => {
        expect(storyBlock(text.replace(/\n/g, '\r\n'), 'F-1.1')).toBe(storyBlock(text, 'F-1.1'));
    });

    it('storyBlock_trailingWhitespaceAndBlankLines_doNotChangeTheBlock', () => {
        const noisy = text.replace('Title F-1.1**\n', 'Title F-1.1**   \n').replace('a.js` (new)\n', 'a.js` (new)\t\n');
        const block = storyBlock(noisy, 'F-1.1');
        expect(block).toBe(storyBlock(text, 'F-1.1'));
        expect(block).toBe(block.trim());
        expect(/[ \t]+\n/.test(block)).toBe(false);
    });

    it('storyBlock_headingStyleStory_runsToTheNextHeading', () => {
        const epic = '## Story 1.1: Engine\n\n**Dependencies:** None\n\nSome text.\n\n## Story 1.2: Saved\n\n**Dependencies:** Story 1.1\n';
        expect(storyBlock(epic, '1.1')).toBe('## Story 1.1: Engine\n\n**Dependencies:** None\n\nSome text.');
        expect(storyBlock(epic, '1.2')).toBe('## Story 1.2: Saved\n\n**Dependencies:** Story 1.1');
    });

    it('storyBlock_lastStoryBeforeARule_stopsAtTheRule', () => {
        const withRule = plan([{ id: 'F-1.1', wave: 1 }]) + '---\n\n## Key Findings\n\nnot part of the story\n';
        const block = storyBlock(withRule, 'F-1.1');
        expect(block).toContain('**Dependencies:** None');
        expect(block).not.toContain('Key Findings');
    });

    it('storyBlock_storyHeaderInsideAFence_isNotAStory', () => {
        const fenced = '```markdown\n* **Story X-1 (S): Example**\n```\n';
        expect(storyBlock(fenced, 'X-1')).toBeNull();
    });
});

describe('AC7: derived waves, ready, isolate, criticalPath', () => {
    // Declared waves are deliberately sparse and different from the derived ones; none violates a dependency.
    const stories = [
        { id: 'F-1.1', wave: 1 },
        { id: 'F-1.2', wave: 2, deps: 'F-1.1' },
        { id: 'F-1.3', wave: 3, deps: 'F-1.2' },
        { id: 'F-1.4', wave: 2, deps: 'F-1.1' },
        { id: 'F-1.5', wave: 5 },
    ];

    it('checkPlan_hardDependencies_deriveTheMinimalTopologicalWaves', () => {
        const result = checkPlan(plan(stories));
        expect(result.errors).toEqual([]);
        expect(result.waves).toEqual([['F-1.1', 'F-1.5'], ['F-1.2', 'F-1.4'], ['F-1.3']]);
    });

    it('checkPlan_hardDependencies_deriveTheCriticalPathByStoryCount', () => {
        expect(checkPlan(plan(stories)).criticalPath).toEqual(['F-1.1', 'F-1.2', 'F-1.3']);
    });

    it('checkPlan_afterField_doesNotChangeDerivedWavesOrDependencies', () => {
        const withAfter = stories.map(s => (s.id === 'F-1.5' ? { ...s, after: 'F-1.3' } : s));
        const result = checkPlan(plan(withAfter));
        expect(result.errors).toEqual([]);
        expect(result.waves).toEqual([['F-1.1', 'F-1.5'], ['F-1.2', 'F-1.4'], ['F-1.3']]);
        expect(result.stories.find(s => s.id === 'F-1.5').dependencies).toEqual([]);
        expect(result.stories.find(s => s.id === 'F-1.5').after).toEqual(['F-1.3']);
    });

    it.each([
        ['nested bullet', '  * **After:** F-1.1, F-1.2\n'],
        ['bare line', '**After:** F-1.1, F-1.2\n'],
    ])('checkPlan_afterField_%s_parsesIdsAndNeverTouchesTheIndex', (_name, line) => {
        const base = plan([{ id: 'F-1.1', wave: 1 }, { id: 'F-1.2', wave: 2, deps: 'F-1.1' }, { id: 'F-1.3', wave: 3 }]);
        const text = base.replace('* **Story F-1.3 (S): Title F-1.3**\n', `* **Story F-1.3 (S): Title F-1.3**\n${line}`);
        const result = checkPlan(text);
        expect(result.errors).toEqual([]);
        expect(result.stories.find(s => s.id === 'F-1.3').after).toEqual(['F-1.1', 'F-1.2']);
        expect(result.stories.find(s => s.id === 'F-1.1').after).toEqual([]);
    });

    it('checkPlan_openStories_areReadyOnlyWhenEveryHardDependencyIsDone', () => {
        const result = checkPlan(plan([
            { id: 'F-1.1', wave: 1, status: '[x]' },
            { id: 'F-1.2', wave: 2, deps: 'F-1.1' },
            { id: 'F-1.3', wave: 3, deps: 'F-1.2' },
            { id: 'F-1.4', wave: 2, deps: 'F-1.1' },
            { id: 'F-1.5', wave: 1, status: '[>]' },
            { id: 'F-1.6', wave: 1, status: '[~]' },
        ]));
        expect(result.ready).toEqual(['F-1.2', 'F-1.4', 'F-1.5']);
    });

    it('checkPlan_afterField_ordersReadyStoriesOnlyAsATiebreak', () => {
        // F-1.1 is listed first but comes After F-1.2, which is also ready: F-1.2 leads. F-1.3 keeps document order.
        const result = checkPlan(plan([
            { id: 'F-1.1', wave: 1, after: 'F-1.2' },
            { id: 'F-1.2', wave: 1 },
            { id: 'F-1.3', wave: 1 },
        ]));
        expect(result.errors).toEqual([]);
        expect(result.ready).toEqual(['F-1.2', 'F-1.1', 'F-1.3']);
    });

    it('checkPlan_afterNamingAStoryThatIsNotReady_doesNotHideTheStory', () => {
        const result = checkPlan(plan([
            { id: 'F-1.1', wave: 1 },
            { id: 'F-1.2', wave: 2, deps: 'F-1.1' },
            { id: 'F-1.3', wave: 1, after: 'F-1.2' },
        ]));
        expect(result.ready).toEqual(['F-1.1', 'F-1.3']);
    });

    it('checkPlan_allStoriesDone_hasNoReadyStories', () => {
        expect(checkPlan(plan([{ id: 'F-1.1', wave: 1, status: '[x]' }])).ready).toEqual([]);
    });
});

