describe('AC6 and AC8: dogfood on real TODOs', () => {
    const cadence = path.resolve('docs/TODO_review-cadence.md');
    const factory = path.resolve('docs/TODO_software-factory.md');

    it('cli_reviewCadenceTodo_exitsZeroWithProseOnlyFilesWarnings', () => {
        const result = run(cadence);
        expect(result.status).toBe(0);
        const json = JSON.parse(result.stdout);
        expect(json.ok).toBe(true);
        expect(json.errors).toEqual([]);
        expect(find(json.warnings, 'FILES_UNRESOLVED').map(w => w.storyId)).toContain('RC-1.3');
        expect(find(json.warnings, 'WAVE_COLLISION')).toEqual([]);
    });

    it('cli_reviewCadenceTodoStrict_exitsOneBecauseProseOnlyFilesBecomeErrors', () => {
        const result = run(cadence, '--strict');
        expect(result.status).toBe(1);
        expect(find(JSON.parse(result.stdout).errors, 'FILES_UNRESOLVED').length).toBeGreaterThanOrEqual(1);
    });

    it('checkPlan_softwareFactoryTodo_validatesWithNoErrors', () => {
        const { readTodoFile } = require('../todo-completion');
        const result = checkPlan(readTodoFile(factory));
        expect(result.errors).toEqual([]);
        expect(result.ok).toBe(true);
        expect(result.stories.length).toBeGreaterThanOrEqual(37);
    });

    it('checkPlan_softwareFactoryTodo_derivedWavesPartitionEveryStoryAfterItsDependencies', () => {
        const { readTodoFile } = require('../todo-completion');
        const result = checkPlan(readTodoFile(factory));
        const flat = result.waves.flat();
        expect(flat.length).toBe(result.stories.length);
        expect(new Set(flat).size).toBe(result.stories.length);
        const waveOf = new Map(result.waves.flatMap((ids, at) => ids.map(id => [id, at])));
        for (const story of result.stories) {
            for (const dep of story.dependencies) expect(waveOf.get(dep), `${story.id} after ${dep}`).toBeLessThan(waveOf.get(story.id));
        }
        expect(result.criticalPath.length).toBeLessThanOrEqual(result.waves.length);
        expect(result.criticalPath.length).toBeGreaterThanOrEqual(2);
    });

    it('cli_softwareFactoryTodo_exitsZero', () => {
        expect(run(factory).status).toBe(0);
    });
});

