// ── SF-2.2: the `**After:**` field (soft ordering) ──
//
// Pinned contract: `After` is an optional body field naming stories this one merely comes after. It never creates a
// hard dependency, so it never produces DEP_ORDER / DEP_CYCLE / UNKNOWN_DEPENDENCY (strict or not), never moves a
// story between derived waves, and is used only as a tiebreak in `ready` ordering. It stays a body field, never a
// Story Index column. SF-2.1 already covers: later-wave After, a mutual After pair, one After in `ready`.

describe('SF-2.2: After is soft ordering and never a finding', () => {
    it.each([[false], [true]])('checkPlan_afterNamingAnUnknownStory_strict%j_isNotAFindingAndKeepsDocumentOrder', (strict) => {
        const result = checkPlan(plan([{ id: 'F-1.1', wave: 1, after: 'F-9.9' }, { id: 'F-1.2', wave: 1 }]), { strict });
        expect(result.errors).toEqual([]);
        expect(result.warnings).toEqual([]);
        expect(result.ok).toBe(true);
        expect(result.ready).toEqual(['F-1.1', 'F-1.2']);
    });

    it.each([[false], [true]])('checkPlan_afterNamingAStoryInALaterWaveAndACycle_strict%j_hasNoErrorsOrWarnings', (strict) => {
        const result = checkPlan(plan([
            { id: 'F-1.1', wave: 1, after: 'F-1.3' },
            { id: 'F-1.2', wave: 1, after: 'F-1.1' },
            { id: 'F-1.3', wave: 2, after: 'F-1.2' },
        ]), { strict });
        expect(result.errors).toEqual([]);
        expect(result.warnings).toEqual([]);
    });

    it('checkPlan_afterNone_parsesToNoIds', () => {
        const result = checkPlan(plan([{ id: 'F-1.1', wave: 1, after: 'None' }]));
        expect(result.stories[0].after).toEqual([]);
        expect(result.ready).toEqual(['F-1.1']);
    });

    it('checkPlan_afterWithProseAroundTheIds_keepsOnlyTheStoryIds', () => {
        const result = checkPlan(plan([
            { id: 'F-1.1', wave: 1 },
            { id: 'F-1.2', wave: 1, after: 'F-1.1 (the template), F-1.3' },
            { id: 'F-1.3', wave: 1 },
        ]));
        expect(result.stories.find(s => s.id === 'F-1.2').after).toEqual(['F-1.1', 'F-1.3']);
        expect(result.errors).toEqual([]);
    });

    it('checkPlan_afterNamingItself_isIgnoredByReadyOrdering', () => {
        const result = checkPlan(plan([{ id: 'F-1.1', wave: 1, after: 'F-1.1' }, { id: 'F-1.2', wave: 1 }]));
        expect(result.errors).toEqual([]);
        expect(result.ready).toEqual(['F-1.1', 'F-1.2']);
    });

    it('checkPlan_afterChain_ordersReadyBackToFront', () => {
        // F-1.1 after F-1.2 after F-1.3: the tiebreak resolves the whole chain, not just one hop.
        const result = checkPlan(plan([
            { id: 'F-1.1', wave: 1, after: 'F-1.2' },
            { id: 'F-1.2', wave: 1, after: 'F-1.3' },
            { id: 'F-1.3', wave: 1 },
        ]));
        expect(result.ready).toEqual(['F-1.3', 'F-1.2', 'F-1.1']);
    });

    it('checkPlan_afterCycleAmongReadyStories_terminatesAndListsEveryStoryOnce', () => {
        const result = checkPlan(plan([
            { id: 'F-1.1', wave: 1, after: 'F-1.2' },
            { id: 'F-1.2', wave: 1, after: 'F-1.3' },
            { id: 'F-1.3', wave: 1, after: 'F-1.1' },
        ]));
        expect(result.errors).toEqual([]);
        expect(result.ready.length).toBe(3);
        expect([...result.ready].sort()).toEqual(['F-1.1', 'F-1.2', 'F-1.3']);
    });

    it('checkPlan_afterOnEveryStory_leavesWavesCriticalPathIsolationAndFindingsUnchanged', () => {
        const base = [
            { id: 'F-1.1', wave: 1, files: '`a.js`' },
            { id: 'F-1.2', wave: 2, deps: 'F-1.1', files: '`b.js`' },
            { id: 'F-1.3', wave: 3, deps: 'F-1.2', files: '`c.js`' },
            { id: 'F-1.4', wave: 2, files: '`b.js`' },
            { id: 'F-1.5', wave: 1, files: '`d.js`' },
        ];
        const soft = base.map((s, at) => ({ ...s, after: base[(at + 2) % base.length].id }));
        const without = checkPlan(plan(base));
        const withAfter = checkPlan(plan(soft));
        expect(withAfter.waves).toEqual(without.waves);
        expect(withAfter.criticalPath).toEqual(without.criticalPath);
        expect(withAfter.isolate).toEqual(without.isolate);
        expect(withAfter.errors).toEqual(without.errors);
        expect(withAfter.warnings).toEqual(without.warnings);
        expect(withAfter.stories.map(s => s.dependencies)).toEqual(without.stories.map(s => s.dependencies));
    });

    it('checkPlan_afterInAHeaderOnlyChecklist_isParsedAndOrdersReady', () => {
        const text = '# T\n\n## Story F-1.1: first\n**Wave:** 1\n**Dependencies:** None\n**After:** F-1.2\n\n## Story F-1.2: second\n**Wave:** 1\n**Dependencies:** None\n';
        const result = checkPlan(text);
        expect(result.stories.find(s => s.id === 'F-1.1').after).toEqual(['F-1.2']);
        expect(result.ready).toEqual(['F-1.2', 'F-1.1']);
    });

    it('checkPlan_afterCellInTheStoryIndex_isNotReadAsTheAfterField', () => {
        // After is a body field; the index row's extra cell never feeds `after`.
        const text = plan([{ id: 'F-1.1', wave: 1 }])
            .replace('| Dependencies |\n|---|---|---|---|---|---|---|---|\n', '| Dependencies | After |\n|---|---|---|---|---|---|---|---|---|\n')
            .replace('| None |\n\n###', '| None | F-1.2 |\n\n###');
        expect(checkPlan(text).stories[0].after).toEqual([]);
    });

    it.each([
        ['Dependencies line', '* **Story F-1.2 (S): Title F-1.2**\n  * **Dependencies:** None\n', '  * **Dependencies:** None · **After:** F-1.1\n'],
        ['Files line', '* **Story F-1.2 (S): Title F-1.2**\n  * **Dependencies:** None\n', '  * **Dependencies:** None\n  * **Files:** `a.js` · **After:** F-1.1\n'],
    ])('checkPlan_afterWrittenInlineAfterAnotherField_%s_isParsed', (_name, anchor, replacement) => {
        const base = plan([{ id: 'F-1.1', wave: 1 }, { id: 'F-1.2', wave: 1 }]);
        const text = base.replace(anchor, `* **Story F-1.2 (S): Title F-1.2**\n${replacement}`);
        expect(text).not.toBe(base);
        const result = checkPlan(text);
        expect(result.stories.find(s => s.id === 'F-1.2').after).toEqual(['F-1.1']);
        expect(result.errors).toEqual([]);
    });

    it('cli_ready_afterOrdersTheReadyArrayAsATiebreak', () => {
        const text = plan([{ id: 'F-1.1', wave: 1, after: 'F-1.2' }, { id: 'F-1.2', wave: 1 }, { id: 'F-1.3', wave: 1 }]);
        withTodo(text, file => {
            const result = run(file, '--ready');
            expect(result.status).toBe(0);
            expect(JSON.parse(result.stdout)).toEqual(['F-1.2', 'F-1.1', 'F-1.3']);
        });
    });
});

describe('SF-2.2: TODOs without After behave identically (the four real shapes)', () => {
    // m9: frozen, trimmed snapshots of the four real TODO shapes (scrubbed of model names and local paths), so the test
    // neither fails when a live TODO is archived or gains an After line nor stops covering the shapes.
    const shapes = ['review-cadence', 'skill-profiles', 'software-factory', 'codereview-remediation'];
    const fixture = name => fs.readFileSync(path.resolve(`.agents/core/__tests__/fixtures/plan-check-shape-${name}.txt`), 'utf8');

    it.each(shapes.map(name => [name]))('checkPlan_realShapeFixture_%s_hasNoAfterAndReadyIsDocumentOrder', (name) => {
        const result = checkPlan(fixture(name));
        expect(result.stories.length).toBeGreaterThan(0);
        for (const story of result.stories) expect(story.after, story.id).toEqual([]);
        // Independent computation: open stories (not done, deferred or blocked) whose hard dependencies are all done.
        const done = new Set(result.stories.filter(s => s.status === 'done').map(s => s.id));
        const expected = result.stories
            .filter(s => !['done', 'deferred', 'blocked'].includes(s.status) && s.dependencies.every(dep => done.has(dep)))
            .map(s => s.id);
        expect(result.ready).toEqual(expected);
    });

    it('realShapeFixtures_doNotReadAnyLiveTodo', () => {
        const source = fs.readFileSync(path.resolve('.agents/core/__tests__/plan-check.test.js'), 'utf8');
        const block = source.slice(source.indexOf("describe('SF-2.2: TODOs without After"), source.indexOf("describe('SF-2.2: /todo and create-project-epics-todo"));
        expect(block).not.toMatch(/docs\/(TODO_|work\/todo)/);
        expect(block).not.toMatch(/readTodoFile/);
    });
});

describe('M3: an inline After on a header story\'s field leaves that field intact (header-only TODO)', () => {
    const headerOnly = fields => '# T\n\n## Story F-1.1: first\n**Release:** core\n**Risk tier:** standard\n**Wave:** 1\n**Dependencies:** None\n\n'
        + `## Story F-1.2: second\n**Release:** core\n**Risk tier:** standard\n${fields}\n\n`
        + '## Story F-1.3: third\n**Release:** core\n**Risk tier:** standard\n**Wave:** 1\n**Dependencies:** None\n';
    const second = result => result.stories.find(s => s.id === 'F-1.2');

    it.each([
        ['a real dependency then After', '**Wave:** 2\n**Dependencies:** F-1.1 · **After:** F-1.3', ['F-1.1'], ['F-1.3']],
        ['None then After', '**Wave:** 2\n**Dependencies:** None · **After:** F-1.3', [], ['F-1.3']],
        ['two dependencies then After', '**Wave:** 2\n**Dependencies:** F-1.1, F-1.3 · **After:** F-1.3', ['F-1.1', 'F-1.3'], ['F-1.3']],
        ['a bullet form', '- **Wave:** 2\n- **Dependencies:** F-1.1 · **After:** F-1.3', ['F-1.1'], ['F-1.3']],
    ])('checkPlan_dependenciesLineWith_%s_keepsTheRealDependenciesAndRaisesNoFinding', (_name, fields, dependencies, after) => {
        const text = headerOnly(fields);

        for (const options of [{}, { strict: true }]) {
            const result = checkPlan(text, options);
            expect(second(result).dependencies).toEqual(dependencies);
            expect(second(result).after).toEqual(after);
            expect(result.errors).toEqual([]);
            expect(codes(result.warnings)).not.toContain('UNKNOWN_DEPENDENCY');
        }
    });

    it('checkPlan_waveLineWithAnInlineAfter_keepsTheWave', () => {
        const result = checkPlan(headerOnly('**Wave:** 2 · **After:** F-1.3\n**Dependencies:** F-1.1'));

        expect(second(result).wave).toBe(2);
        expect(second(result).after).toEqual(['F-1.3']);
        expect(result.errors).toEqual([]);
    });

    it('checkPlan_dependenciesWithAnInlineAfter_stillRaisesDepOrderForARealOrderingError', () => {
        // The cut must not hide the real dependency: F-1.2 (wave 1) depends on F-1.3 (wave 1) is a real DEP_ORDER.
        const result = checkPlan(headerOnly('**Wave:** 1\n**Dependencies:** F-1.3 · **After:** F-1.1'));

        expect(second(result).dependencies).toEqual(['F-1.3']);
        expect(codes(result.errors)).toContain('DEP_ORDER');
    });
});

describe('SF-2.2: /todo and create-project-epics-todo carry the After field (prose pins)', () => {
    const read = rel => fs.readFileSync(path.resolve(rel), 'utf8');
    const todoFlow = read('.agents/skills/todo/references/workflow.md');
    const epicsFlow = read('.agents/skills/create-project-epics-todo/references/workflow.md');
    const between = (text, from, to) => {
        const start = text.indexOf(from);
        const end = text.indexOf(to, start + from.length);
        expect(start, `missing ${from}`).toBeGreaterThanOrEqual(0);
        expect(end, `missing ${to}`).toBeGreaterThan(start);
        return text.slice(start, end);
    };
    const todoTemplate = between(todoFlow, '* **Story {PREFIX}-N.N ({Size}): {Story Title}**', '## Story Index');
    const templateRules = todoFlow.split('\n').filter(line => /^\d+[a-z]?\.\s/.test(line));

    it('todoTemplate_storyBlock_hasOneOptionalAfterLineInTheNestedBulletShape', () => {
        const after = todoTemplate.split('\n').filter(line => line.includes('**After:**'));
        expect(after.length).toBe(1);
        expect(after[0]).toMatch(/^ {2}\* \*\*After:\*\* /);
        expect(after[0]).toMatch(/optional/i);
    });

    it('todoTemplate_afterLine_sitsBetweenDependenciesAndFiles', () => {
        const at = marker => todoTemplate.indexOf(marker);
        expect(at('**Dependencies:**')).toBeGreaterThan(-1);
        expect(at('**After:**')).toBeGreaterThan(at('**Dependencies:**'));
        expect(at('**After:**')).toBeLessThan(at('**Files:**'));
    });

    it('todoTemplateRules_dependenciesIsDefinedAsNeedsOutputOf', () => {
        const rule = templateRules.filter(line => /Dependencies/.test(line) && /needs output of/i.test(line));
        expect(rule.length).toBe(1);
    });

    it('todoTemplateRules_afterIsDefinedAsSoftOrderingNeverAHardDependency', () => {
        const rule = templateRules.filter(line => /\bAfter\b/.test(line) && /soft ordering/i.test(line));
        expect(rule.length).toBe(1);
        expect(rule[0]).toMatch(/never|not a dependency|no dependency/i);
    });

    it('todoStoryIndexHeader_staysWithoutAnAfterColumn', () => {
        const headers = todoFlow.split('\n').filter(line => /^\|\s*Story\s*\|/.test(line));
        expect(headers.length).toBeGreaterThan(0);
        for (const header of headers) expect(header).not.toMatch(/\bAfter\b/);
    });

    it('todoMechanicalChecks_callPlanCheckStrictAndKeepReleaseSliceStrictVerbatim', () => {
        const section = between(todoFlow, '**Mechanical plan checks', 'These checks prove the plan');
        expect(section).toContain('node .claude/core/plan-check.js "{TODO_PATH}" --strict');
        expect(section).toContain('node .claude/core/release-slice.js "{TODO_PATH}" --strict');
    });

    it('epicsTemplate_storyBlock_hasOneOptionalAfterLineAfterDependencies', () => {
        const template = between(epicsFlow, '## Story {N}.1:', '## Story {N}.2');
        const after = template.split('\n').filter(line => line.includes('**After:**'));
        expect(after.length).toBe(1);
        expect(after[0]).toMatch(/^\*\*After:\*\* /);
        expect(after[0]).toMatch(/optional/i);
        expect(template.indexOf('**After:**')).toBeGreaterThan(template.indexOf('**Dependencies:**'));
        expect(template.indexOf('**After:**')).toBeLessThan(template.indexOf('**Unblocks:**'));
    });

    it('epicsOutputRules_afterIsDefinedByPointingAtTodoNotRestated', () => {
        const rules = epicsFlow.split('\n').filter(line => /^\d+\.\s/.test(line) && /\bAfter\b/.test(line));
        expect(rules.length).toBe(1);
        expect(rules[0]).toContain('/todo');
        expect(rules[0]).not.toMatch(/needs output of/i);
    });
});

// ── SF-2.3: /run-todo derives its waves from plan-check (Main Agent authored wiring pins) ──────────────
describe('SF-2.3 run-todo derived-waves wiring', () => {
  const WF = path.resolve(__dirname, '../../skills/run-todo/references/workflow.md');
  const wf = () => fs.readFileSync(WF, 'utf8');

  it('computing a wave plan when the TODO has none calls plan-check --waves', () => {
    const t = wf();
    const at = t.indexOf('If no Wave Plan exists in the TODO');
    expect(at).toBeGreaterThan(0);
    expect(t.slice(at, at + 900)).toContain('node .claude/core/plan-check.js "{TODO_PATH}" --waves');
  });

  it('the structure validation calls plan-check instead of "a short script"', () => {
    const t = wf();
    expect(t).not.toContain('validate structure with a short script');
    const at = t.indexOf('Validate the plan structure');
    expect(at).toBeGreaterThan(0);
    expect(t.slice(at, at + 900)).toContain('node .claude/core/plan-check.js "{TODO_PATH}" --strict');
  });

  it('the TaskList is built from the derived waves and the Wave Breakdown states the derivation', () => {
    const t = wf();
    const tasks = t.slice(t.indexOf('### Step 2: Build the TaskList'), t.indexOf('### Step 3: Write execution plan file'));
    expect(tasks).toMatch(/derived waves/i);
    expect(tasks).toContain('plan-check.js "{TODO_PATH}" --waves');
    const breakdown = t.slice(t.indexOf('## Wave Breakdown'), t.indexOf('## File Ownership Matrix'));
    expect(breakdown).toMatch(/Derived by `plan-check\.js --waves`/);
  });

  it('the wave stays the gate, review and commit unit: no next-wave story starts before its wave', () => {
    const t = wf();
    expect(t).toMatch(/The wave stays the gate, review and commit unit/);
    expect(t).toMatch(/no story of a later wave is dispatched before that wave starts/i);
  });
});

// ── SF-2.6: a worktree per overlapping writer (wiring pins, written before the prose) ──────────────────
describe('SF-2.6 worktree wiring', () => {
  const WF = path.resolve(__dirname, '../../skills/run-todo/references/workflow.md');
  const SKILL = path.resolve(__dirname, '../../skills/using-git-worktrees/SKILL.md');
  const wf = () => fs.readFileSync(WF, 'utf8');
  const skill = () => fs.readFileSync(SKILL, 'utf8');
  const HEADING = '##### Worktree isolation (overlapping writers only)';
  const section = () => {
    const t = wf();
    const at = t.indexOf(HEADING);
    expect(at).toBeGreaterThan(0);
    const end = t.indexOf('Dev agent prompt template:', at);
    expect(end).toBeGreaterThan(at);
    return t.slice(at, end);
  };
  const promptTemplate = () => {
    const t = wf();
    const at = t.indexOf('Dev agent prompt template:');
    return t.slice(at, t.indexOf('**Model selection.**', at));
  };

  it('the isolate list or a git-serial wave gives each writer in the group its own worktree; the others stay shared', () => {
    const s = section();
    expect(s).toContain('node .claude/core/plan-check.js "{TODO_PATH}"');
    expect(s).toMatch(/`isolate` list/);
    expect(s).toMatch(/`git-serial`/);
    expect(s).toMatch(/one worktree per writer/i);
    expect(s).toMatch(/otherwise[^.]*one shared tree and one writer per file/i);
  });

  it('worktrees are created explicitly from local HEAD, never origin default branch, and the Agent isolation parameter is not used', () => {
    const s = section();
    expect(s).toContain('git worktree add');
    expect(s).toMatch(/git worktree add -b "[^"]+" "\{worktree path\}" HEAD/);
    expect(s).toMatch(/wave's base commit[^.]*local HEAD/i);
    expect(s).toMatch(/never[^.]*origin's default branch/i);
    expect(s).toMatch(/unpushed/i);
    expect(s).toContain('AGENTS_WORKTREE_ROOT');
    expect(s).toContain('isolation: "worktree"');
    expect(s).toMatch(/not used[^.]*base commit[^.]*(?:not verified|unverified)/i);
  });

  it('the dispatch prompt carries WORKTREE: {absolute path} and forbids every other absolute path; NO COMMITS is unchanged', () => {
    const p = promptTemplate();
    expect(p).toContain('WORKTREE: {absolute path of this writer\'s worktree, or "none" in the shared tree}');
    expect(p).toMatch(/every other\s+absolute path is forbidden/i);
    expect(p).toContain('NO COMMITS — do not `git add` or `git commit`. The orchestrator (Main Agent) owns');
    expect(p).toContain('all commits: create and modify files only, then report your STATUS.');
    expect(section()).toMatch(/WORKTREE: \{absolute path\}/);
  });

  it('integration is Main Agent only, sequential, merge or cherry-pick without committing, then the Step 5 gate and one Step 8f commit', () => {
    const s = section();
    expect(s).toMatch(/Integration is Main Agent only and sequential/);
    expect(s).toContain('git cherry-pick --no-commit');
    expect(s).toContain('git merge --no-commit --no-ff');
    expect(s).toMatch(/never stash, reset or discard/i);
    expect(s).toMatch(/Step 5 gate/);
    expect(s).toMatch(/one Step 8f commit/);
  });

  it('gates run only in the main checkout and reviewers and research stay read-only in the shared tree', () => {
    const s = section();
    expect(s).toMatch(/gates run only in the main checkout/i);
    expect(s).toMatch(/worktree-local receipt/i);
    expect(s).toMatch(/reviewers and research[^.]*read-only in the shared tree/i);
  });

  it('the cost is stated and the rule applies only to overlapping writers', () => {
    const s = section();
    expect(s).toMatch(/dependency install/i);
    expect(s).toMatch(/clean-baseline run/i);
    expect(s).toMatch(/only to overlapping writers/i);
  });

  it('ac-verify check runs after integration in the main checkout (inert inside a worktree)', () => {
    const s = section();
    expect(s).toMatch(/`ac-verify\.js check`[^.]*after integration[^.]*main checkout/i);
    const t = wf();
    const b3 = t.slice(t.indexOf('#### Step 3b: Lift the freeze'), t.indexOf('#### Step 4: Handle agent statuses'));
    expect(b3).toMatch(/worktree/i);
    expect(b3).toMatch(/after integration/i);
    expect(b3).toMatch(/exact absolute paths/i);
  });

  it('the earlier "separate worktrees may overlap" passages point at the section', () => {
    const t = wf();
    // A passage is a blank-line-separated paragraph (the prompt template wraps the sentence across lines).
    const hits = t.split(/\n\s*\n/).filter(p => /Separate worktrees\s+may\s+overlap/i.test(p));
    expect(hits.length).toBeGreaterThanOrEqual(2);
    for (const passage of hits) expect(passage).toMatch(/Worktree\s+isolation/);
  });

  it('using-git-worktrees gains a per-writer wave section: root from the worktree cwd, .worktreeinclude, pruning', () => {
    const k = skill();
    const at = k.indexOf('## Per-writer worktrees in a wave');
    expect(at).toBeGreaterThan(0);
    const s = k.slice(at, k.indexOf('\n## ', at + 5) > 0 ? k.indexOf('\n## ', at + 5) : undefined);
    expect(s).toContain('git rev-parse --show-toplevel');
    expect(s).toMatch(/not `?CLAUDE_PROJECT_DIR`?/);
    expect(s).toContain('.worktreeinclude');
    expect(s).toContain('git worktree prune');
    expect(s).toMatch(/git worktree add[^\n]*HEAD/);
    expect(s).toMatch(/never `?--force`?/i);
  });
});

// ── Wave 6 review M1/M2/m1: open waves, derived-wave collisions and the exact-set overlap query ──────────────
describe('M1 --waves --open: the run dispatches only open stories of the current slice', () => {
    const REL = (s) => `| ${s.id} | Title ${s.id} | S | ${s.release || 'core'} | standard | ${s.wave === undefined ? '-' : s.wave} | ${s.status || '[ ]'} | ${s.deps || 'None'} |\n`;
    const todo = (stories) => {
        let out = '# TODO: Fixture\n\n## Story Index\n\n' + HEADER;
        for (const s of stories) out += REL(s);
        out += '\n### Epic F-1: Fixture\n\n';
        for (const s of stories) out += bodyOf(s);
        return out;
    };
    // The review's reproduction: done, core, later and blocked stories in one derived layering.
    const stories = [
        { id: 'F-1.1', status: '[x]', files: ['`src/a.js`'] },
        { id: 'F-1.2', deps: 'F-1.1', files: ['`src/b.js`'] },
        { id: 'F-1.3', files: ['`src/c.js`'] },
        { id: 'F-1.4', deps: 'F-1.3', files: ['`src/d.js`'] },
        { id: 'F-1.5', release: 'later', files: ['`src/e.js`'] },
        { id: 'F-1.6', status: '[!]', files: ['`src/f.js`'] },
        { id: 'F-1.7', deps: 'F-1.6', files: ['`src/g.js`'] },
    ];

    it('checkPlan_waves_stillLayersEveryStory_theOpenViewIsASeparateField', () => {
        const result = checkPlan(todo(stories));
        // Every story is layered; the later story never shares a layer with core ones (first adopter run, 2026-11-20).
        expect(result.waves).toEqual([['F-1.1', 'F-1.3', 'F-1.6'], ['F-1.2', 'F-1.4', 'F-1.7'], ['F-1.5']]);
        expect(result.criticalPath[result.criticalPath.length - 1]).toBe('F-1.5');
    });

    it('checkPlan_openWaves_laterApprovedDuringTheCorePhase_trailsTheCoreLayers', () => {
        const result = checkPlan(todo(stories), { laterApproved: true });
        expect(result.errors).toEqual([]);
        expect(result.openWaves).toEqual([['F-1.2', 'F-1.3'], ['F-1.4'], ['F-1.5']]);
    });

    it('checkPlan_openWaves_aLaterStoryDependingOnACoreStory_staysAfterIt', () => {
        const result = checkPlan(todo([{ id: 'F-1.1', files: ['`src/a.js`'] }, { id: 'F-1.2', release: 'later', deps: 'F-1.1', files: ['`src/b.js`'] }]), { laterApproved: true });
        expect(result.openWaves).toEqual([['F-1.1'], ['F-1.2']]);
        expect(result.criticalPath).toEqual(['F-1.1', 'F-1.2']);
    });

    it('checkPlan_openWaves_dropDoneBlockedLaterAndTheStoryWaitingOnABlockedOne', () => {
        const result = checkPlan(todo(stories));
        expect(result.errors).toEqual([]);
        expect(result.openWaves).toEqual([['F-1.2', 'F-1.3'], ['F-1.4']]);
        expect(result.waiting).toEqual([{ id: 'F-1.7', on: 'F-1.6' }]);
    });

    it('checkPlan_openWaves_aDoneDependencyIsSatisfied_soItsDependentIsInTheFirstOpenWave', () => {
        expect(checkPlan(todo(stories)).openWaves[0]).toContain('F-1.2');
    });

    it('checkPlan_openWaves_laterStoriesJoinOnlyAfterTheCoreSliceIsDoneAndTheGoIsRecorded', () => {
        const coreDone = stories.filter(s => s.id !== 'F-1.6' && s.id !== 'F-1.7')
            .map(s => (s.release === 'later' ? s : { ...s, status: '[x]' }));
        const noGo = checkPlan(todo(coreDone));
        expect(noGo.openWaves).toEqual([]); // ship-gate: the later slice waits for the owner's go
        const go = checkPlan(todo(coreDone), { laterApproved: true });
        expect(go.openWaves).toEqual([['F-1.5']]);
    });

    it('checkPlan_openWaves_inProgressStoriesStayInSoAResumeKeepsThem', () => {
        const result = checkPlan(todo([{ id: 'F-1.1', status: '[>]' }, { id: 'F-1.2', deps: 'F-1.1' }]));
        expect(result.openWaves).toEqual([['F-1.1'], ['F-1.2']]);
    });

    it('checkPlan_openWaves_anExternalDependencyThatIsNotDoneKeepsTheStoryOut', () => {
        const external = new Map([['X-9.1', { id: 'X-9.1', release: 'core', status: 'pending', file: 'other.md' }]]);
        const result = checkPlan(todo([{ id: 'F-1.1', deps: 'X-9.1' }, { id: 'F-1.2' }]), { external });
        expect(result.openWaves).toEqual([['F-1.2']]);
        expect(result.waiting).toEqual([{ id: 'F-1.1', on: 'X-9.1' }]);
    });

    it('checkPlan_openWaves_aTodoWithNothingOpenHasNone', () => {
        expect(checkPlan(todo([{ id: 'F-1.1', status: '[x]' }])).openWaves).toEqual([]);
    });

    it('cli_wavesOpen_printsTheOpenLayersAndPlainWavesStaysTheFullGraph', () => {
        withTodo(todo(stories), (file) => {
            const open = run(file, '--waves', '--open');
            expect(open.status).toBe(0);
            expect(JSON.parse(open.stdout)).toEqual([['F-1.2', 'F-1.3'], ['F-1.4']]);
            expect(JSON.parse(run(file, '--waves').stdout)).toEqual([['F-1.1', 'F-1.3', 'F-1.6'], ['F-1.2', 'F-1.4', 'F-1.7'], ['F-1.5']]);
            expect(JSON.parse(run(file, '--waves', '--open', '--later-approved').stdout)).toEqual([['F-1.2', 'F-1.3'], ['F-1.4'], ['F-1.5']]);
        });
    });

    it('cli_wavesOpenWithLaterApproved_addsTheLaterSliceOnceTheCoreIsDone', () => {
        const coreDone = [{ id: 'F-1.1', status: '[x]' }, { id: 'F-1.2', release: 'later', deps: 'F-1.1' }];
        withTodo(todo(coreDone), (file) => {
            expect(JSON.parse(run(file, '--waves', '--open').stdout)).toEqual([]);
            expect(JSON.parse(run(file, '--waves', '--open', '--later-approved').stdout)).toEqual([['F-1.2']]);
        });
    });

    it.each([
        ['--open without --waves', ['--open']],
        ['--later-approved without --waves', ['--later-approved']],
        ['--open twice', ['--waves', '--open', '--open']],
    ])('cli_%s_isInvalidArguments', (_label, args) => {
        withTodo(todo(stories), (file) => {
            const result = run(file, ...args);
            expect(result.status).toBe(2);
            expect(JSON.parse(result.stdout).errors[0].code).toBe('INVALID_ARGUMENTS');
        });
    });

    it('cli_wavesOpenWithReady_printsBoth', () => {
        withTodo(todo(stories), (file) => {
            const out = JSON.parse(run(file, '--ready', '--waves', '--open').stdout);
            expect(out.waves).toEqual([['F-1.2', 'F-1.3'], ['F-1.4']]);
            expect(out.ready).toEqual(['F-1.2', 'F-1.3']);
        });
    });

    // m1: the budget scaling counts open waves and open stories, not the whole graph.
    it('m1_defaultBudgetScalesFromTheOpenWavesAndOpenStories', () => {
        const wf = fs.readFileSync(path.resolve('.agents/skills/run-todo/references/workflow.md'), 'utf8');
        const rule = wf.slice(wf.indexOf('**Set the Budget line when the plan is created'), wf.indexOf('Template:'));
        expect(rule).toMatch(/`minutes` = 60 x open waves/);
        expect(rule).toMatch(/`dispatches` = 8 x open stories/);
    });
});

describe('M2 collisions and isolation for derived waves and for an exact set of stories', () => {
    const rowOf = (s) => `| ${s.id} | Title ${s.id} | S | core | standard | ${s.wave === undefined ? '-' : s.wave} | ${s.status || '[ ]'} | ${s.deps || 'None'} |\n`;
    const todo = (stories, tail = '') => {
        let out = '# TODO: Fixture\n\n## Story Index\n\n' + HEADER;
        for (const s of stories) out += rowOf(s);
        out += '\n### Epic F-1: Fixture\n\n';
        for (const s of stories) out += bodyOf(s);
        return out + tail;
    };
    const shared = [
        { id: 'F-1.1', files: ['`src/a.js`'] },
        { id: 'F-1.2', files: ['`src/a.js`'] },
        { id: 'F-1.3', files: ['`src/a.js`', '`src/b.js`'] },
        { id: 'F-1.4', files: ['`src/c.js`'] },
    ];

    it('checkPlan_threeStoriesSharingAFileInADerivedWave_giveAnIsolateGroupAndAWarning', () => {
        const result = checkPlan(todo(shared));
        expect(result.errors).toEqual([]);
        expect(result.isolate).toEqual([{ wave: 1, derived: true, stories: ['F-1.1', 'F-1.2', 'F-1.3'], paths: ['src/a.js'] }]);
        const warnings = find(result.warnings, 'WAVE_COLLISION');
        expect(warnings).toHaveLength(1);
        expect(warnings[0].message).toMatch(/^Derived wave 1: F-1\.1, F-1\.2 and F-1\.3 all write src\/a\.js; run them in separate worktrees/);
    });

    it('checkPlan_aDerivedWaveCollision_isNeverEscalatedByStrict', () => {
        const result = checkPlan(todo(shared), { strict: true });
        expect(find(result.errors, 'WAVE_COLLISION')).toEqual([]);
        expect(result.ok).toBe(true);
        expect(find(result.warnings, 'WAVE_COLLISION')).toHaveLength(1);
    });

    it('checkPlan_storiesSharingAFileInDifferentDerivedWaves_haveNoGroup', () => {
        const result = checkPlan(todo([
            { id: 'F-1.1', files: ['`src/a.js`'] },
            { id: 'F-1.2', deps: 'F-1.1', files: ['`src/a.js`'] },
        ]));
        expect(result.isolate).toEqual([]);
        expect(find(result.warnings, 'WAVE_COLLISION')).toEqual([]);
    });

    it('checkPlan_aDoneStorySharingAFileWithAnOpenOne_isNotAnIsolationGroup', () => {
        const result = checkPlan(todo([
            { id: 'F-1.1', status: '[x]', files: ['`src/a.js`'] },
            { id: 'F-1.2', files: ['`src/a.js`'] },
        ]));
        expect(result.isolate).toEqual([]);
    });

    it('checkPlan_declaredWaves_keepTheirErrorAndTheirNonDerivedGroup', () => {
        const result = checkPlan(todo([
            { id: 'F-1.1', wave: 1, files: ['`src/a.js`'] },
            { id: 'F-1.2', wave: 1, files: ['`src/a.js`'] },
        ]));
        expect(find(result.errors, 'WAVE_COLLISION')).toHaveLength(1);
        expect(result.isolate).toEqual([{ wave: 1, stories: ['F-1.1', 'F-1.2'], paths: ['src/a.js'] }]);
    });

    it('checkPlan_aTodoWithBothDeclaredAndUndeclaredWaves_collidesEachByItsOwnRule', () => {
        const result = checkPlan(todo([
            { id: 'F-1.1', wave: 1, files: ['`src/a.js`'] },
            { id: 'F-1.2', files: ['`src/b.js`'] },
            { id: 'F-1.3', files: ['`src/b.js`'] },
        ]));
        expect(result.isolate).toEqual([{ wave: 1, derived: true, stories: ['F-1.2', 'F-1.3'], paths: ['src/b.js'] }]);
        expect(find(result.errors, 'WAVE_COLLISION')).toEqual([]);
    });

    it('cli_overlap_answersForTheExactWaveTheRunDispatches_notTheTodosOwnWaves', () => {
        withTodo(todo(shared), (file) => {
            // The run merged F-1.1 and F-1.4 into one wave and split F-1.2 and F-1.3 apart: only the merged pair is asked about.
            expect(JSON.parse(run(file, '--overlap', 'F-1.1,F-1.4').stdout)).toEqual([]);
            expect(JSON.parse(run(file, '--overlap', 'F-1.1,F-1.2').stdout)).toEqual([{ stories: ['F-1.1', 'F-1.2'], paths: ['src/a.js'] }]);
            expect(JSON.parse(run(file, '--overlap', 'F-1.2').stdout)).toEqual([]);
        });
    });

    it('cli_overlap_forADeclaredWaveTodoReportsTheSameGroupsAsIsolate', () => {
        const declared = [
            { id: 'F-1.1', wave: 1, files: ['`src/a.js`'] },
            { id: 'F-1.2', wave: 1, files: ['`src/a.js`'] },
            { id: 'F-1.3', wave: 1, files: ['`src/z.js`'] },
        ];
        withTodo(todo(declared), (file) => {
            const groups = JSON.parse(run(file, '--overlap', 'F-1.1,F-1.2,F-1.3').stdout);
            expect(groups).toEqual([{ stories: ['F-1.1', 'F-1.2'], paths: ['src/a.js'] }]);
        });
    });

    it('cli_overlap_anUnknownStoryIsAnErrorWithExitOne', () => {
        withTodo(todo(shared), (file) => {
            const result = run(file, '--overlap', 'F-1.1,F-9.9');
            expect(result.status).toBe(1);
            expect(JSON.parse(result.stdout).errors[0]).toMatchObject({ code: 'UNKNOWN_STORY' });
        });
    });

    it.each([
        ['an empty id', ['--overlap', 'F-1.1,,F-1.2']],
        ['no value', ['--overlap']],
        ['twice', ['--overlap', 'F-1.1', '--overlap', 'F-1.2']],
        ['with --waves', ['--overlap', 'F-1.1', '--waves']],
        ['with --ready', ['--overlap', 'F-1.1', '--ready']],
    ])('cli_overlap_%s_isInvalidArguments', (_label, args) => {
        withTodo(todo(shared), (file) => {
            const result = run(file, ...args);
            expect(result.status).toBe(2);
            expect(JSON.parse(result.stdout).errors[0].code).toBe('INVALID_ARGUMENTS');
        });
    });
});

// ── Wave 6 review: run-todo workflow pins for M1 M2 M3 M9 and m2 m3 m4 m5 ──────────────────────────────────
describe('Wave 6 review run-todo workflow pins', () => {
    const WF = path.resolve(__dirname, '../../skills/run-todo/references/workflow.md');
    const wf = () => fs.readFileSync(WF, 'utf8');
    const section = (start, end) => {
        const t = wf();
        const from = t.indexOf(start);
        expect(from, `marker ${start}`).toBeGreaterThanOrEqual(0);
        const to = t.indexOf(end, from + start.length);
        expect(to, `end marker ${end}`).toBeGreaterThan(from);
        return t.slice(from, to);
    };
    const isolation = () => section('##### Worktree isolation (overlapping writers only)', 'Dev agent prompt template:');

    describe('M1 the derived waves are the open ones', () => {
        it('phase0Step2AndPhase1Step2CallPlanCheckWithWavesOpen_andDropDoneBlockedDeferredAndLaterStories', () => {
            const step2 = section('If no Wave Plan exists in the TODO', '### 3. Check for existing execution plan');
            expect(step2).toContain('node .claude/core/plan-check.js "{TODO_PATH}" --waves --open --deps-from "{each sibling TODO of the feature}"');
            expect(step2).toMatch(/never a `\[x\]`, `\[!\]`, deferred or later-slice story/);
            expect(step2).toMatch(/`--later-approved` once the plan records the owner's go/);
            expect(step2).toMatch(/A TODO that has its own Wave Plan runs that plan restricted the same way: drop the `\[x\]`, `\[!\]`, deferred and later-slice stories from each wave and the waves left empty/);
            const tasks = section('### Step 2: Build the TaskList', '### Step 3: Write execution plan file');
            expect(tasks).toContain('plan-check.js "{TODO_PATH}" --waves --open --deps-from "{each sibling TODO of the feature}"');
            expect(tasks).toMatch(/derived waves, open stories only/);
        });

        it('theBudgetScalesFromOpenWavesAndOpenStories', () => {
            const rule = section('**Set the Budget line when the plan is created', 'Template:');
            expect(rule).toMatch(/`minutes` = 60 x open waves/);
            expect(rule).toMatch(/`dispatches` = 8 x open stories/);
            expect(rule).toMatch(/done, blocked and later-slice stories do not inflate it/);
        });
    });

    describe('M2 isolation follows the wave the run really dispatches', () => {
        it('theDecisionCallIsOverlapWithTheWaveStoryIds_notTheTodoWideIsolateList', () => {
            const s = isolation();
            expect(s).toContain('node .claude/core/plan-check.js "{TODO_PATH}" --overlap "{wave story IDs}" --deps-from "{each sibling TODO of the feature}"');
            expect(s).toMatch(/covers a wave you merged or split|so a wave you merged or split, and a TODO with no declared waves, are covered/);
            expect(s).toMatch(/`isolate` list[^.]*goes stale once you merge or split, so it is not the decision input/);
        });
    });

    describe('M3 every release-slice, plan-check and story-checkpoint call passes the sibling TODOs', () => {
        it('everyQuotedHelperCallCarriesDepsFrom', () => {
            const calls = [...wf().matchAll(/node \.claude\/core\/(plan-check|story-checkpoint|release-slice)\.js ([^`\n]*)/g)];
            expect(calls.length).toBeGreaterThanOrEqual(8);
            const missing = calls.filter(([, , rest]) => !rest.includes('--deps-from')).map(([whole]) => whole);
            expect(missing).toEqual([]);
        });

        it.each(['plan-check', 'story-checkpoint', 'release-slice'])('%s_isQuotedAtLeastOnce_soTheScanAboveCannotPassEmpty', (helper) => {
            expect(wf()).toContain(`node .claude/core/${helper}.js `);
        });

        it('hashAndCheckUseTheSameListAndSayWhy', () => {
            const t = wf();
            const resume = t.slice(t.indexOf('### 3. Check for existing execution plan'), t.indexOf('### 4. Owner decisions'));
            expect(resume).toMatch(/Use the same `--deps-from` list as the Step 8d `hash` that wrote the checkpoint; a different list hashes differently and reads `STALE_GREEN`/);
            const entry = t.slice(t.indexOf('**8d. Update the execution plan file**'), t.indexOf('**8e.'));
            expect(entry).toMatch(/story-checkpoint\.js hash "\{TODO_PATH\}" \{ID\} --deps-from "\{each sibling TODO of the feature\}"/);
            expect(entry).toMatch(/the same `--deps-from` list as the resume `check`/);
        });
    });

    describe('M9 and m2 to m5 the worktree integration, cleanup and scratch branches', () => {
        it('m2_gitSerialIsDefinedOnceAndItsWritersStillRunInParallelInWorktrees', () => {
            const s = isolation();
            expect(s).toMatch(/`git-serial` means two or more of the wave's stories run `git mv`, `git rm` or `git add`/);
            expect(s).toMatch(/no helper computes it, Main Agent reads the stories' Files and AC/);
            expect(s).toMatch(/Such writers still run in parallel, each in its own worktree, because each worktree has its own index/);
            expect(wf()).not.toMatch(/git-serial waves run sequentially/);
        });

        it('m3_integrationWaitsForStatusTriage_andOnlyDoneWritersAreIntegrated', () => {
            const s = isolation();
            expect(s).toMatch(/after every writer of the group has reported and Step 4a has read its status/);
            expect(s).toMatch(/Integrate only a `DONE` or `DONE_WITH_CONCERNS` writer; leave a `BLOCKED` writer's worktree in place until its story is triaged, and re-dispatch a `NEEDS_CONTEXT` writer into the same worktree path/);
        });

        it('m4_everyEditAfterIntegrationIsRestaged', () => {
            expect(isolation()).toMatch(/after integration `git add -- \{path\}` every file Main Agent edits[^.]*`ship-check\.js verify` refuses `unstaged-code`/);
        });

        it('m5_aLeftoverScratchBranchIsDeletedOnlyWhenNoWorktreeHoldsIt', () => {
            const s = isolation();
            expect(s).toMatch(/A failure because the branch `wave-\{N\}-\{ID\}` already exists is a leftover of an interrupted wave: run `git worktree list`/);
            expect(s).toMatch(/when none does, delete the branch with `git branch -D "wave-\{N\}-\{ID\}"` and create it again/);
            const k = fs.readFileSync(path.resolve(__dirname, '../../skills/using-git-worktrees/SKILL.md'), 'utf8');
            expect(k).toMatch(/A leftover scratch branch makes `git worktree add -b "wave-\{N\}-\{ID\}"` fail: check `git worktree list` first, and delete the branch with `git branch -D` only when no worktree holds it/);
        });

        it('m9_theSnapshotComparesStatusPorcelainWithTheReportedFiles_andAnUnreportedEditIsNeverDroppedUnseen', () => {
            const s = isolation();
            expect(s).toMatch(/First `git -C "\{worktree path\}" status --porcelain` and compare it with the writer's reported files plus the copied Step 2b tests/);
            expect(s).toMatch(/is an unreported edit \(Step 4b failure mode 5\)[^.]*it is never dropped unseen/);
        });

        it('m9_cleanupDeletesTheCopiedTestsByExactPath_checksPorcelainIsEmpty_thenRemovesWithoutForce', () => {
            const s = isolation();
            const cleanup = s.slice(s.indexOf('- Clean up from the main checkout'));
            const rm = cleanup.indexOf('`rm -- {path}`');
            const porcelain = cleanup.indexOf('status --porcelain');
            const remove = cleanup.indexOf('git worktree remove "{worktree path}"');
            expect(rm).toBeGreaterThan(0);
            expect(porcelain).toBeGreaterThan(rm);
            expect(remove).toBeGreaterThan(porcelain);
            expect(cleanup).toMatch(/never `rm -r` and never a glob/);
            expect(cleanup).toMatch(/for each worktree this run created and no other/);
            expect(cleanup).toMatch(/no `--force`: a worktree holding anything unaccounted for stays/);
            expect(cleanup).toMatch(/git branch -D "wave-\{N\}-\{ID\}"/);
            expect(cleanup).toMatch(/git worktree prune/);
            expect(cleanup).not.toMatch(/git worktree remove --force|remove -f /);
        });

        it('theSkillsPruneBulletSaysTheSameThing', () => {
            const k = fs.readFileSync(path.resolve(__dirname, '../../skills/using-git-worktrees/SKILL.md'), 'utf8');
            expect(k).toMatch(/make `remove` refuse: delete them by exact path first \(`rm -- \{path\}`, never `rm -r`\), then confirm `git -C "\$path" status --porcelain` prints nothing/);
        });
    });
});

// The recipe of the worktree section, run for real: the review reproduced `git worktree remove` exiting 128 on a
// writer worktree that holds a copied (untracked) Step 2b test, and an unreported writer edit going unnoticed.
describe('M9 the documented worktree sequence works against real git', () => {
    const { spawnSync: spawn } = require('node:child_process');
    const GIT_ENV = (() => {
        const env = { ...process.env, GIT_TERMINAL_PROMPT: '0' };
        for (const key of Object.keys(env)) if (/^GIT_(DIR|WORK_TREE|INDEX_FILE|COMMON_DIR|PREFIX|NAMESPACE)$/.test(key)) delete env[key];
        return env;
    })();
    const dirs = [];
    afterEach(() => { for (const d of dirs.splice(0)) fs.rmSync(d, { recursive: true, force: true }); });

    function setup() {
        const base = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'wt-seq-')));
        dirs.push(base);
        const main = path.join(base, 'main');
        fs.mkdirSync(main);
        const git = (cwd, ...args) => spawn('git', args, { cwd, encoding: 'utf8', env: GIT_ENV });
        const ok = (cwd, ...args) => {
            const r = git(cwd, ...args);
            expect(r.status, `git ${args.join(' ')}: ${r.stderr}`).toBe(0);
            return r.stdout;
        };
        ok(main, 'init', '-q', '-b', 'main');
        ok(main, 'config', 'user.name', 'T'); ok(main, 'config', 'user.email', 't@example.com'); ok(main, 'config', 'commit.gpgsign', 'false');
        fs.writeFileSync(path.join(main, 'a.js'), '// a v1\n');
        ok(main, 'add', 'a.js'); ok(main, 'commit', '-q', '-m', 'init');
        const wt = path.join(base, 'wt-1');
        ok(main, 'worktree', 'add', '-q', '-b', 'wave-1-F-1.1', wt, 'HEAD');
        // the copied (untracked) Step 2b test, then the writer's reported edit
        fs.mkdirSync(path.join(wt, 'tests'));
        fs.writeFileSync(path.join(wt, 'tests', 'a.test.js'), '// copied test\n');
        fs.writeFileSync(path.join(wt, 'a.js'), '// a v2 by the writer\n');
        return { base, main, wt, git, ok };
    }
    const porcelain = (t) => t.ok(t.wt, 'status', '--porcelain').split('\n').filter(Boolean);
    const snapshot = (t, files) => {
        t.ok(t.wt, 'add', '--', ...files);
        fs.writeFileSync(path.join(t.base, 'msg'), 'snapshot\n');
        t.ok(t.wt, 'commit', '-q', '-F', path.join(t.base, 'msg'));
    };

    it('thePlainRemoveTheReviewFlaggedFailsOnTheCopiedTest_exit128', () => {
        const t = setup();
        snapshot(t, ['a.js']);

        const r = t.git(t.main, 'worktree', 'remove', t.wt);

        expect(r.status).toBe(128);
        expect(r.stderr).toMatch(/contains modified or untracked files/);
        expect(fs.existsSync(t.wt)).toBe(true);
    });

    it('theStatusPorcelainSnapshotStep_listsTheReportedEditTheCopiedTestAndAnyUnreportedEdit', () => {
        const t = setup();
        fs.writeFileSync(path.join(t.wt, 'surprise.txt'), 'the writer touched a file it did not report\n');

        const lines = porcelain(t);
        const reported = ['a.js'];
        const copied = ['tests/'];
        const extras = lines.map((l) => l.slice(3)).filter((f) => !reported.includes(f) && !copied.includes(f));

        expect(lines.map((l) => l.slice(3)).sort()).toEqual(['a.js', 'surprise.txt', 'tests/']);
        expect(extras).toEqual(['surprise.txt']);
    });

    it('theDocumentedCleanup_removesTheCopiedTestByExactPath_thenPlainRemoveBranchDeleteAndPruneSucceed', () => {
        const t = setup();
        snapshot(t, ['a.js']);
        // integrate: cherry-pick without committing; the main index changes only here
        t.ok(t.main, 'cherry-pick', '--no-commit', 'wave-1-F-1.1');
        expect(t.ok(t.main, 'status', '--porcelain')).toBe('M  a.js\n');
        expect(fs.existsSync(path.join(t.main, '.git', 'CHERRY_PICK_HEAD'))).toBe(false);

        // cleanup per the workflow: exact-path rm of the copied test, empty porcelain, remove without --force, branch -D, prune
        fs.rmSync(path.join(t.wt, 'tests', 'a.test.js'));
        fs.rmdirSync(path.join(t.wt, 'tests'));
        expect(porcelain(t)).toEqual([]);
        t.ok(t.main, 'worktree', 'remove', t.wt);
        t.ok(t.main, 'branch', '-D', 'wave-1-F-1.1');
        t.ok(t.main, 'worktree', 'prune');

        expect(fs.existsSync(t.wt)).toBe(false);
        expect(t.ok(t.main, 'worktree', 'list', '--porcelain').split('\n').filter((l) => l.startsWith('worktree '))).toHaveLength(1);
        expect(t.ok(t.main, 'branch', '--list', 'wave-1-F-1.1').trim()).toBe('');
    });

    it('anUnreportedEdit_keepsTheWorktree_theCleanupStopsAtTheNonEmptyPorcelainAndPlainRemoveRefuses', () => {
        const t = setup();
        fs.writeFileSync(path.join(t.wt, 'surprise.txt'), 'unreported\n');
        snapshot(t, ['a.js']);
        fs.rmSync(path.join(t.wt, 'tests', 'a.test.js'));
        fs.rmdirSync(path.join(t.wt, 'tests'));

        expect(porcelain(t)).toEqual(['?? surprise.txt']);
        const refused = t.git(t.main, 'worktree', 'remove', t.wt);

        expect(refused.status).toBe(128);
        expect(fs.readFileSync(path.join(t.wt, 'surprise.txt'), 'utf8')).toBe('unreported\n');
    });

    it('m4_aMainAgentEditAfterTheCherryPickLeavesTheIndexDifferingUntilItIsRestaged', () => {
        const t = setup();
        snapshot(t, ['a.js']);
        t.ok(t.main, 'cherry-pick', '--no-commit', 'wave-1-F-1.1');

        fs.writeFileSync(path.join(t.main, 'a.js'), '// a v3 conflict resolution\n');
        expect(t.ok(t.main, 'diff', '--name-only').trim()).toBe('a.js'); // unstaged: ship-check verify would refuse this

        t.ok(t.main, 'add', '--', 'a.js');
        expect(t.ok(t.main, 'diff', '--name-only').trim()).toBe('');
    });

    it('m5_aLeftoverScratchBranchBlocksWorktreeAddUntilItIsDeletedAfterCheckingTheList', () => {
        const t = setup();
        snapshot(t, ['a.js']);
        // an interrupted wave: the directory vanished, the registration and the branch remain
        fs.rmSync(t.wt, { recursive: true, force: true });
        const again = path.join(t.base, 'wt-2');
        const blocked = t.git(t.main, 'worktree', 'add', '-q', '-b', 'wave-1-F-1.1', again, 'HEAD');
        expect(blocked.status).not.toBe(0);

        expect(t.ok(t.main, 'worktree', 'list', '--porcelain')).toMatch(/prunable/);
        t.ok(t.main, 'worktree', 'prune');
        t.ok(t.main, 'branch', '-D', 'wave-1-F-1.1');
        t.ok(t.main, 'worktree', 'add', '-q', '-b', 'wave-1-F-1.1', again, 'HEAD');

        expect(fs.existsSync(path.join(again, 'a.js'))).toBe(true);
    });
});
